fn game(db: &Connection, code: &str) -> AppResult<Game> {
    db.query_row("SELECT id, quiz_id, code, title, questions, phase, current_question, version FROM games WHERE code=?", [code], |r| {
        let raw: String = r.get(4)?;
        let questions = serde_json::from_str(&raw).map_err(|e| rusqlite::Error::FromSqlConversionFailure(4, rusqlite::types::Type::Text, Box::new(e)))?;
        Ok(Game { id: r.get(0)?, quiz_id: r.get(1)?, code: r.get(2)?, title: r.get(3)?, questions, phase: r.get(5)?, index: r.get(6)?, version: r.get(7)? })
    }).optional()?.ok_or(AppError::NotFound)
}
fn player(db: &Connection, game: &Game, headers: &HeaderMap) -> AppResult<Option<Player>> {
    let name = format!("quizzy_player_{}", game.code);
    let token = headers.get(header::COOKIE).and_then(|h| h.to_str().ok())
        .and_then(|cookies| cookies.split(';').find_map(|part| {
            let (key, value) = part.trim().split_once('=')?;
            (key == name).then_some(value)
        }));
    let Some(token) = token else { return Ok(None) };
    Ok(db.query_row("SELECT id, name, token FROM players WHERE game_id=? AND token=?", params![game.id, token], |r| {
        Ok(Player { id: r.get(0)?, name: r.get(1)?, token: r.get(2)? })
    }).optional()?)
}
