#[derive(Default)]
pub struct Hub {
    rooms: Mutex<HashMap<i64, Room>>,
    stopping: std::sync::atomic::AtomicBool,
}
struct Room {
    changed: watch::Sender<u64>,
    players: HashMap<i64, Presence>,
}
struct Presence {
    connections: usize,
    seen: Instant,
}
impl Default for Room {
    fn default() -> Self {
        Self {
            changed: watch::channel(0).0,
            players: HashMap::new(),
        }
    }
}
impl Hub {
    pub fn shutdown(&self) {
        self.stopping
            .store(true, std::sync::atomic::Ordering::Relaxed);
        for room in self.rooms.lock().unwrap().values() {
            room.changed.send_modify(|v| *v = v.wrapping_add(1));
        }
    }
    fn subscribe(&self, game: i64) -> watch::Receiver<u64> {
        self.rooms
            .lock()
            .unwrap()
            .entry(game)
            .or_default()
            .changed
            .subscribe()
    }
    fn notify(&self, game: i64) {
        if let Some(room) = self.rooms.lock().unwrap().get_mut(&game) {
            room.changed
                .send_modify(|version| *version = version.wrapping_add(1));
        }
    }
    fn connected(&self, game: i64, player: i64) {
        let mut rooms = self.rooms.lock().unwrap();
        let room = rooms.entry(game).or_default();
        let presence = room.players.entry(player).or_insert(Presence {
            connections: 0,
            seen: Instant::now(),
        });
        presence.connections += 1;
        presence.seen = Instant::now();
        room.changed.send_modify(|v| *v = v.wrapping_add(1));
    }
    fn disconnected(&self, game: i64, player: i64) {
        let mut rooms = self.rooms.lock().unwrap();
        if let Some(room) = rooms.get_mut(&game) {
            if let Some(presence) = room.players.get_mut(&player) {
                presence.connections = presence.connections.saturating_sub(1);
                if presence.connections == 0 {
                    room.players.remove(&player);
                }
            }
            room.changed.send_modify(|v| *v = v.wrapping_add(1));
        }
    }
    fn heartbeat(&self, game: i64, player: i64) {
        let mut rooms = self.rooms.lock().unwrap();
        if let Some(room) = rooms.get_mut(&game)
            && let Some(presence) = room.players.get_mut(&player)
        {
            let expired = presence.seen.elapsed() > Duration::from_secs(45);
            presence.seen = Instant::now();
            if expired {
                room.changed.send_modify(|v| *v = v.wrapping_add(1));
            }
        }
    }
    fn active(&self, game: i64) -> Vec<i64> {
        self.rooms
            .lock()
            .unwrap()
            .get(&game)
            .map(|room| {
                room.players
                    .iter()
                    .filter(|(_, p)| {
                        p.connections > 0 && p.seen.elapsed() <= Duration::from_secs(45)
                    })
                    .map(|(id, _)| *id)
                    .collect()
            })
            .unwrap_or_default()
    }
}
struct PresenceGuard {
    app: AppState,
    game: i64,
    player: Option<i64>,
}
impl Drop for PresenceGuard {
    fn drop(&mut self) {
        if let Some(player) = self.player {
            self.app.live.disconnected(self.game, player);
        }
    events(app, code, headers, false)
}
fn events(app: AppState, code: String, headers: HeaderMap, moderator: bool) -> AppResult<Response> {
    let (id, pid) = {
        let db = app.db.lock().unwrap();
        let g = game(&db, &code)?;
        let pid = if moderator || g.phase == "ended" {
            None
        } else {
            player(&db, &g, &headers)?.map(|p| p.id)
        };
        (g.id, pid)
    };
    // Subscribe before reading state so changes during connection setup aren't lost.
    let mut changed = app.live.subscribe(id);
    if let Some(pid) = pid {
        app.live.connected(id, pid);
    }
    let guard = PresenceGuard {
        app: app.clone(),
        game: id,
        player: pid,
    };
    let stream = async_stream::stream! {
        let _guard = guard;
        let mut previous = String::new();
        let mut sent = Instant::now();
        loop {
            if app.live.stopping.load(std::sync::atomic::Ordering::Relaxed) { break; }
            changed.borrow_and_update();
            let state = match snapshot(&app, &code, &headers, moderator) {
                Ok(state) => state,
                Err(_) => { yield Ok::<Event, Infallible>(Event::default().event("unavailable").data("Game unavailable")); break; }
            };
            let done = state["phase"] == "ended";
            let data = serde_json::to_string(&state).unwrap();
            let mut visible = state;
            visible.as_object_mut().unwrap().remove("revision");
            let fingerprint = serde_json::to_string(&visible).unwrap();
            if fingerprint != previous {
                yield Ok::<Event, Infallible>(Event::default().event("state").retry(Duration::from_secs(2)).data(data));
                previous = fingerprint;
                sent = Instant::now();
            } else if sent.elapsed() >= Duration::from_secs(10) {
                yield Ok::<Event, Infallible>(Event::default().event("ping").data("1"));
                sent = Instant::now();
            }
            if done { break; }
            tokio::select! {
                _ = changed.changed() => {},
                _ = tokio::time::sleep(Duration::from_secs(10)) => {},
            }
            // One slow phone never queues the whole room's answer traffic. Watch
            // retains only the latest change; short bursts become one snapshot.
            tokio::time::sleep(Duration::from_millis(75)).await;
        }
    };
    let mut response = Sse::new(stream)
        .keep_alive(KeepAlive::new().interval(Duration::from_secs(12)))
        .into_response();
    response
        .headers_mut()
        .insert("x-accel-buffering", HeaderValue::from_static("no"));
    response
        .headers_mut()
        .insert(header::CACHE_CONTROL, HeaderValue::from_static("no-store"));
    Ok(response)
}

pub fn history(db: &Connection, quiz_id: i64) -> AppResult<String> {
    use std::fmt::Write;
    let mut stmt = db.prepare("SELECT code, phase FROM games WHERE quiz_id=? ORDER BY id DESC")?;
    let mut html = String::new();
    for row in stmt.query_map([quiz_id], |r| {
        Ok((r.get::<_, String>(0)?, r.get::<_, String>(1)?))
    })? {
        let (code, phase) = row?;
        let _ = write!(
            html,
            r#"<li class="card game-row"><a href="/moderate/games/{code}">Game {code}</a><span class="badge">{phase}</span></li>"#
        );
    }
    if html.is_empty() {
        Ok(html)
    } else {
        Ok(format!(
            r#"<section class="section"><h2>Games</h2><ul class="list-reset game-history" aria-label="Games">{html}</ul></section>"#
        ))
    }
}

